/**
 * Demo art: small pixel-art PNGs generated at runtime (data URLs) so the demo needs no
 * asset files. Deliberately simple, hand-tuned shapes; real art will replace them later.
 *
 * This is a temporary demo harness (Module 03 is awaiting approval; the demo exists so the
 * project owner can see the engine working). It is not part of the engine.
 */

type Ctx = CanvasRenderingContext2D;

function makeCanvas(width: number, height: number): { canvas: HTMLCanvasElement; g: Ctx } {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const g = canvas.getContext('2d');
  if (g === null) throw new Error('2D canvas context unavailable');
  g.imageSmoothingEnabled = false;
  return { canvas, g };
}

function pngUrl(canvas: HTMLCanvasElement): string {
  return canvas.toDataURL('image/png');
}

function px(g: Ctx, x: number, y: number, color: string): void {
  g.fillStyle = color;
  g.fillRect(x, y, 1, 1);
}

function rect(g: Ctx, x: number, y: number, w: number, h: number, color: string): void {
  g.fillStyle = color;
  g.fillRect(x, y, w, h);
}

/** Deterministic PRNG so the world looks the same on every visit. */
function mulberry32(seed: number): () => number {
  let a = seed | 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Draws with wrap-around so the tiled ground never shows a seam. */
function drawWrapped(size: number, x: number, y: number, draw: (gx: number, gy: number) => void): void {
  for (const ox of [-size, 0, size]) {
    for (const oy of [-size, 0, size]) {
      draw(x + ox, y + oy);
    }
  }
}

export function groundPngUrl(): string {
  const size = 96;
  const { canvas, g } = makeCanvas(size, size);
  const rnd = mulberry32(1405);
  const base = '#c89858';
  const light = '#d5a766';
  const light2 = '#e2b878';
  const dark = '#b0813f';
  const darker = '#9c6f33';
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const r = rnd();
      px(g, x, y, r < 0.06 ? light2 : r < 0.2 ? light : r < 0.38 ? dark : r < 0.46 ? darker : base);
    }
  }
  // pebbles
  for (let i = 0; i < 14; i++) {
    const x = Math.floor(rnd() * size);
    const y = Math.floor(rnd() * size);
    drawWrapped(size, x, y, (gx, gy) => {
      rect(g, gx, gy, 2, 1, '#8a7154');
      px(g, gx + 1, gy - 1, '#a58c66');
    });
  }
  // dry grass tufts
  for (let i = 0; i < 8; i++) {
    const x = Math.floor(rnd() * size);
    const y = Math.floor(rnd() * size);
    drawWrapped(size, x, y, (gx, gy) => {
      px(g, gx + 1, gy, '#a08a3c');
      px(g, gx, gy + 1, '#8a7530');
      px(g, gx + 2, gy + 1, '#98823a');
      px(g, gx + 1, gy + 2, '#7d6a2c');
    });
  }
  // short cracks
  for (let i = 0; i < 5; i++) {
    let x = Math.floor(rnd() * size);
    let y = Math.floor(rnd() * size);
    const len = 3 + Math.floor(rnd() * 3);
    for (let s = 0; s < len; s++) {
      drawWrapped(size, x, y, (gx, gy) => px(g, gx, gy, '#96692f'));
      x += rnd() < 0.5 ? 1 : 0;
      y += 1;
    }
  }
  return pngUrl(canvas);
}

export function cactusPngUrl(): string {
  const { canvas, g } = makeCanvas(16, 24);
  const O = '#24401f';
  const B = '#3f7a36';
  const D = '#2c5a28';
  const H = '#5c9c48';
  // trunk (outline then body, rounded top)
  rect(g, 5, 3, 6, 21, O);
  rect(g, 6, 4, 4, 20, B);
  rect(g, 9, 4, 1, 20, D);
  rect(g, 6, 4, 1, 20, H);
  px(g, 5, 4, O); // round the top corners
  px(g, 10, 4, O);
  // left arm
  rect(g, 0, 6, 4, 10, O);
  rect(g, 1, 7, 2, 8, B);
  px(g, 1, 7, H);
  rect(g, 3, 11, 3, 3, O);
  rect(g, 3, 12, 3, 2, B);
  // right arm
  rect(g, 12, 9, 4, 9, O);
  rect(g, 13, 10, 2, 7, B);
  px(g, 13, 10, H);
  rect(g, 10, 14, 3, 3, O);
  rect(g, 10, 15, 3, 2, B);
  // spines
  px(g, 6, 6, '#dce8c4');
  px(g, 9, 10, '#dce8c4');
  px(g, 6, 15, '#dce8c4');
  px(g, 9, 19, '#dce8c4');
  return pngUrl(canvas);
}

export function rockPngUrl(): string {
  const { canvas, g } = makeCanvas(16, 12);
  const O = '#3d3227';
  const B = '#7e6f5c';
  const L = '#96856f';
  const D = '#655747';
  const widths: readonly number[] = [6, 10, 13, 15, 16, 16, 15, 13, 10, 7];
  for (let y = 0; y < widths.length; y++) {
    const w = widths[y] ?? 0;
    const x0 = Math.floor((16 - w) / 2);
    rect(g, x0, y + 1, w, 1, O);
    rect(g, x0 + 1, y + 1, w - 2, 1, y < 4 ? L : B);
    if (y >= 6) rect(g, x0 + 1, y + 1, w - 2, 1, D);
    rect(g, x0 + 1, y + 1, Math.max(1, Math.floor(w / 3)), 1, y < 5 ? L : B);
  }
  return pngUrl(canvas);
}

export function shackPngUrl(): string {
  const { canvas, g } = makeCanvas(64, 48);
  const roofDark = '#42301e';
  const roof = '#57402a';
  const roofLight = '#6b4f33';
  const wall = '#7d5a36';
  const wallDark = '#6a4a2b';
  const plankLine = '#5c3f24';
  const door = '#332214';
  const frame = '#4f3a22';
  // roof (low trapezoid, ridge highlight)
  for (let y = 0; y < 13; y++) {
    const inset = Math.floor((12 - y) * 2.4);
    rect(g, inset, y + 4, 64 - inset * 2, 1, y < 5 ? roof : roofDark);
  }
  rect(g, 31, 4, 2, 13, roofLight);
  // walls with plank lines
  rect(g, 4, 17, 56, 31, wall);
  for (let y = 20; y < 48; y += 4) rect(g, 4, y, 56, 1, plankLine);
  rect(g, 4, 17, 56, 1, wallDark);
  rect(g, 4, 17, 1, 31, wallDark);
  rect(g, 59, 17, 1, 31, wallDark);
  // door
  rect(g, 27, 25, 12, 23, frame);
  rect(g, 28, 26, 10, 22, door);
  px(g, 36, 36, '#8a7154');
  // window
  rect(g, 12, 23, 10, 10, frame);
  rect(g, 13, 24, 8, 8, '#2a2e38');
  rect(g, 16, 24, 1, 8, frame);
  rect(g, 13, 27, 8, 1, frame);
  px(g, 14, 25, '#9db3c9');
  // ground shadow
  rect(g, 2, 47, 60, 1, '#3a2a18');
  return pngUrl(canvas);
}

export function fencePngUrl(): string {
  const { canvas, g } = makeCanvas(32, 16);
  const post = '#6b4a2c';
  const postDark = '#523721';
  const rail = '#7a5633';
  const O = '#332415';
  for (const x of [3, 26]) {
    rect(g, x - 1, 3, 4, 13, O);
    rect(g, x, 4, 2, 11, post);
    px(g, x, 4, '#8a6740');
    rect(g, x - 1, 3, 4, 1, postDark);
  }
  for (const y of [6, 11]) {
    rect(g, 0, y, 32, 2, O);
    rect(g, 1, y, 30, 1, rail);
  }
  px(g, 4, 6, O);
  px(g, 27, 7, O);
  return pngUrl(canvas);
}

/**
 * Player spritesheet: 6 frames of 16x24 (96x24 total).
 * Frame 0 idle, frames 1-4 walk cycle, frame 5 spare for later art.
 */
export function playerSheetPngUrl(): string {
  const { canvas, g } = makeCanvas(96, 24);
  const O = '#2a1c12';
  const hat = '#6b4423';
  const hatDark = '#513018';
  const skin = '#e0a878';
  const shirt = '#3e5f8a';
  const shirtDark = '#324c6e';
  const vest = '#5a3a24';
  const pants = '#4a4a52';
  const boot = '#2e2118';

  for (let f = 0; f < 6; f++) {
    const ox = f * 16;
    // hat
    rect(g, ox + 4, 1, 8, 3, hat);
    rect(g, ox + 3, 4, 10, 1, hat);
    rect(g, ox + 4, 3, 8, 1, hatDark);
    px(g, ox + 4, 1, O);
    px(g, ox + 11, 1, O);
    // head
    rect(g, ox + 5, 5, 6, 4, skin);
    px(g, ox + 9, 6, O); // eye (faces right; left is a flip)
    rect(g, ox + 6, 8, 4, 1, '#b9805a'); // neck shade
    // torso
    rect(g, ox + 4, 9, 8, 7, shirt);
    rect(g, ox + 4, 9, 2, 7, vest);
    rect(g, ox + 10, 9, 2, 7, vest);
    rect(g, ox + 4, 15, 8, 1, shirtDark);
    // arms (swing opposite to the legs)
    const armDx = f === 1 ? 1 : f === 3 ? -1 : 0;
    rect(g, ox + 3 + armDx, 10, 1, 4, shirt);
    px(g, ox + 3 + armDx, 14, skin);
    rect(g, ox + 12 - armDx, 10, 1, 4, shirt);
    px(g, ox + 12 - armDx, 14, skin);
    // legs + boots per frame
    const legSets: Array<[number, number]> = [
      [0, 0], // idle / passing
      [2, -2], // stride
      [0, 0], // passing
      [-2, 2], // stride (other leg)
      [0, 0], // passing
      [0, 0],
    ];
    const legs = legSets[f] ?? [0, 0];
    const [lx, rx] = legs;
    rect(g, ox + 5 + lx, 16, 3, 6, pants);
    rect(g, ox + 8 + rx, 16, 3, 6, pants);
    rect(g, ox + 4 + lx, 22, 4, 2, boot);
    rect(g, ox + 8 + rx, 22, 4, 2, boot);
    // outline accents
    px(g, ox + 4, 9, O);
    px(g, ox + 11, 9, O);
    px(g, ox + 5 + lx, 22, O);
    px(g, ox + 11 + rx, 22, O);
  }
  return pngUrl(canvas);
}
