/**
 * DemoScene: a small western scene that exists only to show the engine working.
 * It is not gameplay and not part of the engine; it is the demo harness the project
 * owner asked for while Modules 01-03 await approval.
 *
 * What it shows:
 * - render (Module 02): pixel-perfect scaling, textures loaded through the TextureCatalog
 * - input (Module 03): actions drive the character, effect keys work while paused
 * - camera (Module 03): follow with a dead zone, world bounds, zoom, shake, kick, fade
 */
import Phaser from 'phaser';
import type { CameraApi, CameraTarget } from '../camera';
import type { InputApi } from '../input';

export const DEMO_SCENE_KEY = 'demo';

export const WORLD_WIDTH = 1600;
export const WORLD_HEIGHT = 900;

/** Sprites satisfy this shape (x, y, active). */
type Player = Phaser.GameObjects.Sprite & CameraTarget;

export interface DemoSceneApis {
  readonly input: InputApi;
  readonly camera: CameraApi;
}

interface PropSpec {
  readonly key: string;
  readonly originY: number;
  readonly count: number;
  readonly avoidCenter: number;
}

export class DemoScene extends Phaser.Scene {
  private readonly apis: DemoSceneApis;
  private player: Player | undefined;
  private zoomedIn = false;

  constructor(apis: DemoSceneApis) {
    super(DEMO_SCENE_KEY);
    this.apis = apis;
  }

  create(): void {
    this.buildWorld();
    this.buildPlayer();
    this.wireCamera();
    this.wireEffectKeys();
  }

  private buildWorld(): void {
    this.add
      .tileSprite(0, 0, WORLD_WIDTH, WORLD_HEIGHT, 'demo-ground')
      .setOrigin(0, 0)
      .setDepth(0);

    const rnd = (() => {
      let a = 1405 | 0;
      return () => {
        a = (a + 0x6d2b79f5) | 0;
        let t = Math.imul(a ^ (a >>> 15), 1 | a);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
      };
    })();

    const specs: readonly PropSpec[] = [
      { key: 'demo-shack', originY: 1, count: 5, avoidCenter: 260 },
      { key: 'demo-cactus', originY: 1, count: 26, avoidCenter: 140 },
      { key: 'demo-rock', originY: 1, count: 30, avoidCenter: 0 },
    ];
    for (const spec of specs) {
      let placed = 0;
      let guard = 0;
      while (placed < spec.count && guard < spec.count * 50) {
        guard++;
        const x = 40 + rnd() * (WORLD_WIDTH - 80);
        const y = 60 + rnd() * (WORLD_HEIGHT - 80);
        const cx = WORLD_WIDTH / 2;
        const cy = WORLD_HEIGHT / 2;
        if (Math.abs(x - cx) < spec.avoidCenter && Math.abs(y - cy) < spec.avoidCenter) continue;
        this.add.image(Math.round(x), Math.round(y), spec.key).setOrigin(0.5, spec.originY).setDepth(1);
        placed++;
      }
    }
    // a fence line near the first shack row
    for (let x = 620; x < 900; x += 32) {
      this.add.image(x, 690, 'demo-fence').setOrigin(0.5, 1).setDepth(1);
    }
  }

  private buildPlayer(): void {
    this.anims.create({
      key: 'demo-walk',
      frames: this.anims.generateFrameNumbers('demo-player', { start: 1, end: 4 }),
      frameRate: 9,
      repeat: -1,
    });
    this.player = this.add
      .sprite(WORLD_WIDTH / 2, WORLD_HEIGHT / 2, 'demo-player', 0)
      .setOrigin(0.5, 1)
      .setDepth(2);
  }

  private wireCamera(): void {
    const player = this.player;
    if (player === undefined) throw new Error('demo scene built in the wrong order');
    this.apis.camera.setBounds({ x: 0, y: 0, width: WORLD_WIDTH, height: WORLD_HEIGHT });
    this.apis.camera.follow(player, { snap: true });
    // Push the current view into this new Scene's camera once (see CameraApi.refresh).
    this.apis.camera.refresh();
  }

  private wireEffectKeys(): void {
    const camera = this.apis.camera;
    // Immediate listeners: they fire from the key event itself, even while paused.
    this.apis.input.onPress('primaryAction', () => camera.shake({ intensity: 2.5, durationMs: 350 }));
    this.apis.input.onPress('secondaryAction', () => camera.kick(3, -2, 240));
    this.apis.input.onPress('crouch', () => {
      this.zoomedIn = !this.zoomedIn;
      camera.zoomTo(this.zoomedIn ? 2 : 1, { durationMs: 450 });
    });
    this.apis.input.onPress('interact', () => {
      camera.fadeOut({ durationMs: 400 });
      window.setTimeout(() => camera.fadeIn({ durationMs: 400 }), 750);
    });
  }

  override update(_time: number, delta: number): void {
    const player = this.player;
    if (player === undefined) return;
    const input = this.apis.input;
    const dx = input.axis('moveLeft', 'moveRight');
    const dy = input.axis('moveUp', 'moveDown');
    const speed = (input.isDown('sprint') ? 150 : 84) * (delta / 1000);
    let vx = dx * speed;
    let vy = dy * speed;
    if (dx !== 0 && dy !== 0) {
      vx *= Math.SQRT1_2;
      vy *= Math.SQRT1_2;
    }
    player.setX(Phaser.Math.Clamp(player.x + vx, 8, WORLD_WIDTH - 8));
    player.setY(Phaser.Math.Clamp(player.y + vy, 30, WORLD_HEIGHT));
    if (dx !== 0) player.setFlipX(dx < 0);
    const moving = dx !== 0 || dy !== 0;
    if (moving && !player.anims.isPlaying) player.play('demo-walk');
    if (!moving && player.anims.isPlaying) {
      player.stop();
      player.setFrame(0);
    }
  }
}
