/**
 * Demo composition root (temporary demo harness, not the game's composition root).
 * Wires the same systems as src/main.ts, then loads runtime-generated pixel art through
 * the render module's TextureCatalog and starts the DemoScene.
 *
 * Controls are shown in demo.html. `?debug` enables the same diagnostics hook the
 * browser tests use.
 */
import { ConfigStore } from '../config/ConfigStore';
import { createConfig } from '../config/engineConfig';
import { BrowserScreenFade, CameraSystem } from '../camera';
import { Application, defineSystemId, type PauseReason, type System } from '../core';
import {
  createPhaserCameraGateway,
  createPhaserRenderGateway,
  PHASER_HOST_ID,
  PhaserHost,
  pixelArtGameConfigProvider,
} from '../core/phaser';
import { BrowserKeyboardEnvironment, InputSystem } from '../input';
import { BrowserFullscreen, BrowserViewportSource, RenderSystem, type RenderApi } from '../render';
import { cactusPngUrl, fencePngUrl, groundPngUrl, playerSheetPngUrl, rockPngUrl, shackPngUrl } from './pixelArt';
import { DemoScene } from './DemoScene';

const debug = new URLSearchParams(window.location.search).has('debug');

function showError(title: string, message: string): void {
  const box = document.getElementById('engine-error');
  if (!box) return;
  const heading = document.createElement('h1');
  heading.textContent = title;
  const text = document.createElement('p');
  text.textContent = message.replace(/^\[[A-Z_]+\]\s*/, '');
  box.replaceChildren(heading, text);
  box.hidden = false;
}

async function loadDemoTextures(render: RenderApi): Promise<void> {
  const t = render.textures;
  await Promise.all([
    t.loadImage('demo-ground', groundPngUrl()),
    t.loadImage('demo-cactus', cactusPngUrl()),
    t.loadImage('demo-rock', rockPngUrl()),
    t.loadImage('demo-shack', shackPngUrl()),
    t.loadImage('demo-fence', fencePngUrl()),
    t.loadSpriteSheet('demo-player', playerSheetPngUrl(), {
      frameWidth: 16,
      frameHeight: 24,
      margin: 0,
      spacing: 0,
    }),
  ]);
}

async function main(): Promise<void> {
  const mode = import.meta.env.PROD ? 'production' : 'development';
  const config = new ConfigStore(createConfig(mode));
  const parent = document.getElementById(config.values.host.parentElementId);
  if (!parent) throw new Error(`The page has no element with id '${config.values.host.parentElementId}'`);

  const host = new PhaserHost({ configProvider: pixelArtGameConfigProvider });
  const render = new RenderSystem({
    gateway: createPhaserRenderGateway(host.api),
    viewport: new BrowserViewportSource(parent),
    fullscreen: new BrowserFullscreen(parent),
    dependsOn: [PHASER_HOST_ID],
  });
  const input = new InputSystem({ environment: new BrowserKeyboardEnvironment(window, document) });
  const camera = new CameraSystem({
    gateway: createPhaserCameraGateway(host.api),
    fade: new BrowserScreenFade(parent),
    dependsOn: [PHASER_HOST_ID],
  });
  const app = new Application({ config, frameSource: host.frameSource });

  app.errors.onReport((report) => {
    if (report.severity === 'fatal') showError('The game stopped', report.error.message);
  });

  app.register(host);
  app.register(render);
  app.register(input);
  app.register(camera);

  if (debug) {
    const probe: System = {
      id: defineSystemId<undefined>('frame-probe'),
      api: undefined,
      update: (frame) => {
        document.body.dataset['frames'] = String(frame.frame);
      },
    };
    app.register(probe);
    app.events.on('app:lifecycle-changed', ({ to }) => {
      document.body.dataset['lifecycle'] = to;
    });
    Object.defineProperty(window, '__engineDebug', {
      value: Object.freeze({
        pause: (reason: PauseReason) => {
          app.pause(reason);
        },
        resume: (reason: PauseReason) => {
          app.resume(reason);
        },
        shutdown: () => app.shutdown(),
        lifecycle: () => app.lifecycleState,
        reasons: () => app.reasons,
        game: () => host.api.game,
        render: () => render.api,
        input: () => input.api,
        camera: () => camera.api,
      }),
    });
  }

  try {
    await app.init();
    await app.start();
  } catch (error) {
    showError('The game could not start', error instanceof Error ? error.message : String(error));
    await app.shutdown().catch((shutdownError: unknown) => {
      app.errors.report(shutdownError, 'main', 'fatal');
    });
    return;
  }

  // Escape / P toggles pause. Immediate listeners fire even while paused, so the same
  // listener resumes the game again.
  let paused = false;
  input.api.onPress('pause', () => {
    paused = !paused;
    if (paused) app.pause('manual');
    else app.resume('manual');
  });

  try {
    await loadDemoTextures(render.api);
    host.api.game.scene.add('demo', new DemoScene({ input: input.api, camera: camera.api }), true);
  } catch (error) {
    showError('The demo could not load', error instanceof Error ? error.message : String(error));
  }
}

main().catch((error: unknown) => {
  showError('The game could not start', error instanceof Error ? error.message : String(error));
});
